using System.ComponentModel.DataAnnotations;

namespace MineSafety.Api.Entities;

// Maps to the Reports table (database/schema/008_Reports.sql), the main table in the system.
public class Report
{
    public int ReportId { get; set; }              // ReportID (primary key, identity)

    [MaxLength(50)]
    public string ReportNumber { get; set; } = ""; // readable reference shown to users, unique

    // Generated by the phone when the report is created (possibly offline) and sent again on
    // every retry, so the server can spot a repeated upload and return the existing report.
    // Unique in SQL.
    public Guid ClientReportId { get; set; }

    public int ReporterAccountId { get; set; }
    public Account Reporter { get; set; } = null!;

    public int IncidentTypeId { get; set; }
    public IncidentType IncidentType { get; set; } = null!;

    public int LocationId { get; set; }
    public Location Location { get; set; } = null!;

    public int StatusId { get; set; }
    public ReportStatus Status { get; set; } = null!;

    public string Description { get; set; } = "";  // required in SQL (may be an empty string)

    public DateTime OccurredAt { get; set; }       // when it actually happened underground (UTC)

    // How many photos and voice notes the phone said it would upload after the report.
    // The evidence is complete once that many have arrived. Null means unknown (reports created
    // before migration 003) and is treated as "nothing expected".
    public int? ExpectedImageCount { get; set; }
    public int? ExpectedVoiceNoteCount { get; set; }

    public bool IsActive { get; set; } = true;
    public DateTime CreatedAt { get; set; }        // when the row was created on the server
    public DateTime? UpdatedAt { get; set; }
    public DateTime? SubmittedAt { get; set; }     // when the server received it

    [Timestamp]
    public byte[] RowVersion { get; set; } = Array.Empty<byte>();

    public List<ReportAttachment> Attachments { get; set; } = new();
    public List<ReportReview> Reviews { get; set; } = new();
}
